def camel_to_snake(s: str) -> str:
    """Convert camelCase or PascalCase to snake_case.

    Consecutive capitals stay together (e.g. HTTPServer -> http_server).
    """
    if not s:
        return s
    result = []
    length = len(s)
    for i, ch in enumerate(s):
        if ch.isupper():
            # Determine if an underscore is needed
            if i > 0:
                prev = s[i - 1]
                next_char = s[i + 1] if i + 1 < length else ''
                if prev.islower() or (prev.isupper() and next_char.islower()):
                    result.append('_')
            result.append(ch.lower())
        else:
            result.append(ch)
    return ''.join(result)

