def is_holiday(date: str) -> bool:
    """True if date is a company holiday per calendars/company_2025.ics."""
    base = pathlib.Path(__file__).parent.parent / "calendars" / "company_2025.ics"
    try:
        content = base.read_text(encoding="utf-8")
    except FileNotFoundError:
        return False
    # Find all DTSTART lines
