            if len(parts) == 2:
                raw = parts[1].strip()
                # handle possible TZID etc but assume plain date
                m = re.match(r"(\d{8})", raw)
                if m:
                    d = m.group(1)
                    dates.add(f"{d[:4]}-{d[4:6]}-{d[6:]}")
    return date in dates

